import unittest

from solucao import encaixar


class TestInserirNoMeio(unittest.TestCase):
    def test_insere_no_meio(self):
        """encaixar poe o item na posicao pedida"""
        self.assertEqual(encaixar([["a", 1], ["b", 2]], 1, ["c", 3]), [["a", 1], ["c", 3], ["b", 2]])

    def test_insere_no_comeco(self):
        """encaixar na posicao 0 poe no comeco"""
        self.assertEqual(encaixar([["a", 1], ["b", 2]], 0, ["z", 0]), [["z", 0], ["a", 1], ["b", 2]])

    def test_insere_no_fim(self):
        """encaixar na posicao igual ao tamanho poe no fim"""
        self.assertEqual(encaixar([["a", 1]], 1, ["b", 2]), [["a", 1], ["b", 2]])

    def test_posicao_invalida_fica_queta(self):
        """encaixar devolve a lista sem mexer quando a posicao nao existe"""
        self.assertEqual(encaixar([["a", 1], ["b", 2]], 9, ["c", 3]), [["a", 1], ["b", 2]])
        self.assertEqual(encaixar([["a", 1], ["b", 2]], -1, ["c", 3]), [["a", 1], ["b", 2]])

